"""
Traffic Generator Module for SOSDN Simulation
Models user service demands and background traffic loads.
Reference: Beshley et al., JCN 2024, Section VII, Fig. 10.
"""

from typing import Dict, List, Any
import numpy as np

class FlowDemand:
    """Represents an active communication flow generated by a user."""
    def __init__(
        self,
        flow_id: str,
        user_id: int,
        service_type: str,
        service_class: str,
        source_switch: str,
        target_service: str,
        bandwidth_mbps: float,
        sla_qoe_target: float,
        is_sla_sensitive: bool = False
    ):
        self.flow_id = flow_id
        self.user_id = user_id
        self.service_type = service_type
        self.service_class = service_class  # 'A', 'B', 'C', 'D', 'E', 'F'
        self.source_switch = source_switch
        self.target_service = target_service  # 'IPTV', 'VOIP', 'WEB', 'VOD'
        self.bandwidth_mbps = bandwidth_mbps
        self.sla_qoe_target = sla_qoe_target
        self.is_sla_sensitive = is_sla_sensitive
        
        # Runtime assigned attributes
        self.selected_server_id: str = ""
        self.destination_switch: str = ""
        self.assigned_category: int = 3  # 1, 2, or 3
        self.relative_priority: float = 0.0
        self.dscp_code: str = "001000"
        self.active_path: List[str] = []

class TrafficGenerator:
    """Generates the 50 user flows and background traffic for experimental scenarios."""
    def __init__(self, config: Dict[str, Any], topology):
        self.config = config
        self.topology = topology
        self.flows: List[FlowDemand] = []
        self._initialize_user_flows()

    def _initialize_user_flows(self):
        """
        Creates exactly 50 user flows matching the paper:
        - Users 1 to 20: IPTV users (Class C, 4.096 Mbps, 720p H.264 video)
          * Users 1 to 10: Strict SLA QoE = 5.0 (as shown in Paper Fig. 10!)
          * User 7: Highlighted test subject experiencing degradation under baseline
        - Users 21 to 30: VoIP users (Class A, 0.064 Mbps, G.711 UDP)
        - Users 31 to 40: Web users (Class D, 2.048 Mbps, HTTP)
        - Users 41 to 50: VoD users (Class E, 2.048 Mbps, Media on Demand)
        Total = 50 users.
        """
        user_dist = self.config['users']['distribution']
        total_users = self.config['users']['total_users']
        
        # 1. 20 IPTV users (Users 1 to 20)
        for iptv_idx in range(1, user_dist['iptv'] + 1):
            uid = iptv_idx
            src_sw = self.topology.get_user_location(uid)
            is_strict_sla = (iptv_idx <= 10)
            target_qoe = 5.0 if is_strict_sla else 4.0
            self.flows.append(FlowDemand(
                flow_id=f"flow_iptv_{uid}",
                user_id=uid,
                service_type="IPTV",
                service_class="C",
                source_switch=src_sw,
                target_service="IPTV",
                bandwidth_mbps=4096.0 / 1000.0,
                sla_qoe_target=target_qoe,
                is_sla_sensitive=is_strict_sla
            ))

        # 2. 10 VoIP users (Users 21 to 30)
        for voip_idx in range(1, user_dist['voip'] + 1):
            uid = 20 + voip_idx
            src_sw = self.topology.get_user_location(uid)
            self.flows.append(FlowDemand(
                flow_id=f"flow_voip_{uid}",
                user_id=uid,
                service_type="VoIP",
                service_class="A",
                source_switch=src_sw,
                target_service="VOIP",
                bandwidth_mbps=64.0 / 1000.0,
                sla_qoe_target=4.0,
                is_sla_sensitive=True
            ))

        # 3. 10 Web users (Users 31 to 40)
        for web_idx in range(1, user_dist['web'] + 1):
            uid = 30 + web_idx
            src_sw = self.topology.get_user_location(uid)
            self.flows.append(FlowDemand(
                flow_id=f"flow_web_{uid}",
                user_id=uid,
                service_type="Web",
                service_class="D",
                source_switch=src_sw,
                target_service="WEB",
                bandwidth_mbps=2048.0 / 1000.0,
                sla_qoe_target=3.5,
                is_sla_sensitive=False
            ))

        # 4. 10 VoD users (Users 41 to 50)
        for vod_idx in range(1, user_dist['vod'] + 1):
            uid = 40 + vod_idx
            src_sw = self.topology.get_user_location(uid)
            self.flows.append(FlowDemand(
                flow_id=f"flow_vod_{uid}",
                user_id=uid,
                service_type="VoD",
                service_class="E",
                source_switch=src_sw,
                target_service="VOD",
                bandwidth_mbps=2048.0 / 1000.0,
                sla_qoe_target=3.5,
                is_sla_sensitive=False
            ))

        assert len(self.flows) == total_users, f"Expected {total_users} flows, got {len(self.flows)}"

    def get_flows(self, rate_multiplier: float = 1.0) -> List[FlowDemand]:
        """Returns deep copies of flow demands scaled by the scenario rate multiplier."""
        scaled_flows = []
        for f in self.flows:
            scaled = FlowDemand(
                flow_id=f.flow_id,
                user_id=f.user_id,
                service_type=f.service_type,
                service_class=f.service_class,
                source_switch=f.source_switch,
                target_service=f.target_service,
                bandwidth_mbps=f.bandwidth_mbps * rate_multiplier,
                sla_qoe_target=f.sla_qoe_target,
                is_sla_sensitive=f.is_sla_sensitive
            )
            scaled_flows.append(scaled)
        return scaled_flows

    def inject_background_traffic(self, scenario_name: str, seed: int):
        """Applies scenario-specific background cross-traffic on core links."""
        np.random.seed(seed)
        sc_config = self.config['scenarios'][scenario_name]
        bg_bw = sc_config['background_traffic_mbps']
        bottlenecks = sc_config.get('bottleneck_links', [])

        for u, v, d in self.topology.graph.edges(data=True):
            if d.get('type') == 'core_link':
                jitter_val = np.random.uniform(0.85, 1.15)
                load = bg_bw * jitter_val
                
                # Check if this link is a designated bottleneck
                if [u, v] in bottlenecks:
                    # Heavily loaded core path (e.g. SW4-SW1)
                    load = min(98.5, load * 1.25 + 15.0)
                
                d['current_load_mbps'] += load
